INSERT INTO ghost.facilities(code,name,square_feet) VALUES ('GH01','Ghost Warehouse Regional DC',80000) ON CONFLICT DO NOTHING;
INSERT INTO ghost.zones(facility_id,code,name,zone_type) SELECT facility_id,v.code,v.name,v.kind FROM ghost.facilities CROSS JOIN (VALUES ('RCV','Receiving','RECEIVING'),('QAR','Quality and Returns','QUALITY'),('BLK','Bulk Reserve','STORAGE'),('SML','Small Parts','STORAGE'),('MED','Medium Parts','STORAGE'),('HVY','Heavy Parts','STORAGE'),('SEC','High Value','STORAGE'),('PCK','Packing','PACKING'),('SHP','Shipping','SHIPPING')) v(code,name,kind) WHERE ghost.facilities.code='GH01' ON CONFLICT DO NOTHING;
